begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id) values('a6000000-0000-4000-8000-000000000001'),('a6000000-0000-4000-8000-000000000002');
insert into profiles(id,display_name,consented_at) values('a6000000-0000-4000-8000-000000000001','Fixture',now()),('a6000000-0000-4000-8000-000000000002','Outsider',now());
insert into families(id,name) values('a6000000-0000-4000-8000-000000000003','Fixture');
insert into family_members(family_id,user_id,role,relationship) values('a6000000-0000-4000-8000-000000000003','a6000000-0000-4000-8000-000000000001','owner','father');
insert into children(id,family_id,name,birth_date,sex) values('a6000000-0000-4000-8000-000000000004','a6000000-0000-4000-8000-000000000003','Fixture',current_date,'female');
insert into child_records(id,child_id,service,kind,occurred_at,note,record_timezone,created_by) values('a6000000-0000-4000-8000-000000000005','a6000000-0000-4000-8000-000000000004','growth','observation',now(),'Fixture','UTC','a6000000-0000-4000-8000-000000000001');
insert into child_record_photos(id,child_id,record_id,path,content_type,size_bytes,uploaded_by) values('a6000000-0000-4000-8000-000000000006','a6000000-0000-4000-8000-000000000004','a6000000-0000-4000-8000-000000000005','fixture/variants-test.png','image/png',100,'a6000000-0000-4000-8000-000000000001');
select set_config('request.jwt.claims','{"sub":"a6000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select ok(child_photo_access('fixture/variants-test.png.display-v1-480.webp',true),'uploader can upload derivative');
select ok(not child_photo_access('fixture/variants-test.png.display-v1-480.webp',false),'incomplete derivative is not readable');
select throws_ok($$select complete_child_photo_variants('a6000000-0000-4000-8000-000000000006')$$,'23514','variants_missing','both files required');
reset role;
insert into storage.objects(bucket_id,name,created_at) values('child-care-photos','fixture/variants-test.png.display-v1-480.webp',now()-interval '2 days'),('child-care-photos','fixture/variants-test.png.display-v1-1600.webp',now()-interval '2 days');
set local role authenticated;
select lives_ok($$select complete_child_photo_variants('a6000000-0000-4000-8000-000000000006')$$,'uploader completes derivatives');
select ok(child_photo_access('fixture/variants-test.png.display-v1-1600.webp',false),'authorized family can read completed derivative');
select ok(not child_photo_access('fixture/variants-test.png.display-v1-800.webp',true),'unregistered sizes denied');
reset role;
select queue_orphan_photos();
select is((select count(*)::int from child_photo_cleanup where path like 'fixture/variants-test%'),0,'live variants are not orphan cleanup candidates');
select set_config('request.jwt.claims','{"sub":"a6000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select ok(not child_photo_access('fixture/variants-test.png.display-v1-480.webp',false),'outsider cannot read private derivative');
select throws_ok($$select complete_child_photo_variants('a6000000-0000-4000-8000-000000000006')$$,'42501','forbidden','outsider cannot mark complete');
reset role;
delete from child_record_photos where id='a6000000-0000-4000-8000-000000000006';
select is((select count(*)::int from child_photo_cleanup where path like 'fixture/variants-test%'),3,'photo deletion queues original and both variants');
select * from finish();
rollback;
